}
// e: r0 with 32-bit address math and plain store
__global__ void __launch_bounds__(128) ve_k(const float* __restrict__ x, float* __restrict__ y, int n) {
  unsigned row = blockIdx.y; unsigned col = (blockIdx.x*128+threadIdx.x)*8;
  const float* g = x + (row*(2u*INNER) + col); float gv[8], lv[8], ov[8];
  ld8(g, gv); ld8(g+INNER, lv);
  #pragma unroll
  for (int i=0;i<8;++i) ov[i]=geglu(gv[i],lv[i]);
  st8(y+(row*INNER+col), ov);
}
