names = ["empty","one","kb","r0","ro","va","vb","vc","vd","ve"]
K = {n: bp.cuda_kernel(SRC, n+"_k") for n in names}
def ref(x):
    a,b = x.chunk(2,dim=-1); return torch.nn.functional.gelu(a,approximate='tanh')*b
def cfg(name, rows):
    tot = rows*640
    if name=="empty": return None
    if name in ("r0","ro","ve","vd"): return ((5,rows),(128,))
    if name=="va": return ((10,rows),(64,))
    if name=="vb": return (((tot+511)//512,),(512,))
    if name=="vc": return (((tot+511)//512,),(256,))
res = {}
def mk(name, rows, x, y):
    tot = rows*640
    if name=="empty_1": return lambda x,y: K["empty"]((1,),(128,),x,y,0)
    if name=="empty_640": return lambda x,y: K["empty"]((640,),(128,),x,y,0)
    if name=="empty_1280": return lambda x,y: K["empty"]((1280,),(64,),x,y,0)
    if name=="one": return lambda x,y: K["one"]((1,),(1,),x,y,0)
    if name=="kb148": return lambda x,y: K["kb"]((148,),(128,),x,y,0)
    g,b = cfg(name, rows)
    return lambda x,y: K[name](g,b,x,y,tot)
